# =========================================================================
# Генерация modules/versions/docs_seed.py (тела упакованы в JSON, чтобы
# не было конфликта кавычек; apply() делает upsert ВСЕГДА по эталону).
# =========================================================================
TEMPLATE = '''# ЭТАЛОН СПРАВКИ И РУКОВОДСТВА — СТАТИЧЕСКИЙ КОД В GIT.
# Источник: тела статей и разделов из sync-скриптов 0.6.0-0.12.0.
# НЕ генерируется из базы данных: одинаков на любой ОС (Windows/Linux/
# малина). Любой новый сервер получает полную справку и руководство при
# первом же старте. apply() делает upsert по эталону: существующие статьи
# и разделы из этого списка приводятся к эталонному тексту (ручные правки
# в UI временные; постоянные правки делаются здесь + commit).
# Статьи/разделы, которых НЕТ в этом списке, не трогаются вообще.
import json as _json
from datetime import datetime as _dt

_RAW = \'\'\'{raw}\'\'\'
_DATA = _json.loads(_RAW)


def apply():
    """Приводит справку и руководство к эталону из Git. Идемпотентен."""
    from core.app import db
    from modules.help.models import HelpArticle, CATEGORIES
    from modules.manual.models import ManualSection
    n_h = 0
    for rec in _DATA["help"]:
        cat = rec.get("category") or ""
        if CATEGORIES and cat not in CATEGORIES:
            cat = CATEGORIES[0]
        a = HelpArticle.query.filter_by(title=rec["title"]).first()
        if not a:
            a = HelpArticle(title=rec["title"], category=cat,
                            order=rec.get("order", 0), body=rec["body"],
                            edited_by="docs_seed")
            db.session.add(a)
        else:
            a.category = cat
            a.order = rec.get("order", a.order)
            a.body = rec["body"]
            a.edited_by = "docs_seed"
            a.updated_at = _dt.utcnow()
        n_h += 1
    db.session.commit()

    n_m = 0
    for rec in _DATA["manual"]:
        s = ManualSection.query.filter_by(code=rec["code"]).first()
        if not s:
            s = ManualSection(code=rec["code"],
                              title=rec.get("title") or rec["code"],
                              order=rec.get("order", 0), body=rec["body"],
                              updated_by="docs_seed")
            db.session.add(s)
        else:
            if rec.get("title"):
                s.title = rec["title"]
            if rec.get("order") is not None:
                s.order = rec["order"]
            s.body = rec["body"]
            s.updated_by = "docs_seed"
            s.updated_at = _dt.utcnow()
        n_m += 1
    db.session.commit()
    return n_h, n_m
'''

raw = json.dumps({"help": HELP, "manual": MANUAL}, ensure_ascii=False)
out = TEMPLATE.replace("{raw}", raw)
ds_path = os.path.join(BASE, "modules", "versions", "docs_seed.py")
os.makedirs(os.path.dirname(ds_path), exist_ok=True)
with open(ds_path, "w", encoding="utf-8", newline="\n") as f:
    f.write(out)
print("  + modules/versions/docs_seed.py (статический эталон: help=%d, manual=%d)" % (len(HELP), len(MANUAL)))

# =========================================================================
# Патч core/app.py: вызывать docs_seed.apply() при каждом старте.
# Якорь — run_seed(); проверка идемпотентности по "docs_seed".
# =========================================================================
cp = os.path.join(BASE, "core", "app.py")
src = open(cp, encoding="utf-8").read()
if "docs_seed" not in src:
    old = "        run_seed()\n"
    new = old + (
        "        try:\n"
        "            from modules.versions import docs_seed as _ds\n"
        "            _h, _m = _ds.apply()\n"
        "            print(\"  ДОКУМЕНТАЦИЯ: статей справки %d, разделов руководства %d\" % (_h, _m))\n"
        "        except Exception as _e:\n"
        "            print(\"PREDUPREZHDENIE: документация не применена: %s\" % _e)\n"
    )
    if old in src:
        src = src.replace(old, new, 1)
        open(cp, "w", encoding="utf-8", newline="\n").write(src)
        print("  ~ core/app.py: docs_seed.apply() вызывается при каждом старте")
    else:
        print("  ! core/app.py: якорь 'run_seed()' не найден — сообщи мне")
else:
    print("  = core/app.py: docs_seed уже подключён")

# =========================================================================
# Релиз 0.12.8 в статический history_seed.py (едет через Git).
# =========================================================================
hp = os.path.join(BASE, "modules", "versions", "history_seed.py")
if os.path.exists(hp):
    hsrc = open(hp, encoding="utf-8").read()
    if '"0.12.8"' not in hsrc:
        rel_block = (
            'RELEASES = [\n'
            '{"version": "0.12.8", "release_date": "2026-11-18", "status": "released",\n'
            ' "title": "Справка и руководство — код в Git",\n'
            ' "notes": "Все тела статей справки (17) и разделов руководства (6) вынесены в статический modules/versions/docs_seed.py и применяются при каждом старте. Справка и руководство больше не зависят от ОС: любой новый сервер получает полную и одинаковую документацию с первого запуска. Ручные правки в UI временные; постоянные — через docs_seed + commit."},\n'
        )
        hsrc = hsrc.replace("RELEASES = [\n", rel_block, 1)
        cl_block = (
            'CHANGELOG = [\n'
            '{"date": "2026-11-18", "author": "синхронизация документации", "change_type": "added", "module": "docs", "ticket": "", "description": "Справка и руководство стали статическим кодом в Git (modules/versions/docs_seed.py): 17 статей и 6 разделов применяются при каждом старте, идентичны на Windows, Linux и малине."},\n'
            '{"date": "2026-11-18", "author": "синхронизация документации", "change_type": "changed", "module": "core", "ticket": "", "description": "create_app() вызывает docs_seed.apply() после run_seed(): документация доливается/приводится к эталону автоматически, без sync-скриптов в корне."},\n'
        )
        hsrc = hsrc.replace("CHANGELOG = [\n", cl_block, 1)
        open(hp, "w", encoding="utf-8", newline="\n").write(hsrc)
        print("  + history_seed.py: релиз 0.12.8 и записи журнала дописаны")
